def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "pick_webcam": And([
            Not(self.area_clear(self.desk)),  # Area not clear
            self.robot_has_sensor,  # Sensor available
            self.safety_check_active  # Safety check active
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
